#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1'000'000'007;

long long power(long long base, long long exp, long long mod) {   // 빠른 거듭제곱
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;        // mod < 2^31 이라 곱해도 long long 안이에요
        exp >>= 1;
    }
    return result;
}

int main() {
    long long a = 84, b = 120;
    cout << "gcd " << gcd(a, b) << '\n';         // C++17 <numeric>
    cout << "lcm " << a / gcd(a, b) * b << '\n'; // lcm(a, b) 도 있어요

    cout << "2^10 " << power(2, 10, MOD) << '\n';
    cout << "3^200 % MOD " << power(3, 200, MOD) << '\n';

    long long inv = power(5, MOD - 2, MOD);      // MOD 가 소수일 때 페르마 소정리로 역원
    cout << "5의 역원 " << inv << ' ' << 5 * inv % MOD << '\n';
    cout << "10 / 5 (mod) " << 10 * inv % MOD << '\n';

    // 약수 나열: i * i <= n 까지만 보고 짝을 같이 넣기
    long long n = 36;
    vector<long long> divs;
    for (long long i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            divs.push_back(i);
            if (i != n / i) divs.push_back(n / i);
        }
    }
    sort(divs.begin(), divs.end());
    cout << "36의 약수";
    for (long long d : divs) cout << ' ' << d;
    cout << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

bool isPrime(long long x) {
    if (x < 2) return false;             // 0, 1 은 소수가 아니에요
    for (long long i = 2; i * i <= x; i++)   // i 를 long long 으로 둬야 i * i 가 안 넘쳐요
        if (x % i == 0) return false;
    return true;
}

int main() {
    vector<long long> xs = {1, 2, 9, 17, 97, 1000000007};
    for (long long x : xs)
        if (isPrime(x)) cout << x << ' ';
    cout << '\n';

    // 에라토스테네스의 체: 0..N 의 소수 여부를 한 번에
    int N = 50;
    vector<bool> sieve(N + 1, true);
    sieve[0] = sieve[1] = false;
    for (int i = 2; (long long)i * i <= N; i++)
        if (sieve[i])
            for (int j = i * i; j <= N; j += i) sieve[j] = false;
    vector<int> primes;
    for (int i = 0; i <= N; i++)
        if (sieve[i]) primes.push_back(i);
    cout << primes.size();
    for (int p : primes) cout << ' ' << p;
    cout << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    // C++: / 는 0 쪽으로 자르고, % 의 부호는 나뉘는 수를 따라가요
    int cases[4][2] = {{7, 2}, {-7, 2}, {7, -2}, {-7, -2}};
    for (auto &c : cases) {
        int a = c[0], b = c[1];
        cout << a << ' ' << b << ' ' << a / b << ' ' << a % b << '\n';
    }

    int MOD = 5;
    int x = -12;
    cout << "나머지 " << ((x % MOD) + MOD) % MOD << '\n';  // 0..MOD-1 로 맞추기
    // 내림 몫이 필요하면 직접 고쳐요
    int a = -7, b = 2;
    int q = a / b;
    if ((a % b != 0) && ((a < 0) != (b < 0))) q--;
    cout << "내림 몫 " << q << '\n';
    return 0;
}
